def test_parse_edge_list_skips_comments():
    g = parse_edge_list("# exported by roadtool\na b 2\n# end of file\n")
    assert g.nodes == ["a", "b"]

def test_dfs_handles_long_chains():
    g = Graph.from_edges([(i, i + 1) for i in range(5000)], directed=True)
    assert len(dfs(g, 0)) == 5001

def test_len_is_number_of_nodes(city, grid):
    assert len(city) == 5
    assert len(grid) == 12
